import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"API et webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"fr/car-wash/api.md","filePath":"fr/car-wash/api.md"}'),c={name:"fr/car-wash/api.md"};function s(n,e,r,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="api-et-webhooks" tabindex="-1">API et webhooks <a class="header-anchor" href="#api-et-webhooks" aria-label="Permalink to &quot;API et webhooks&quot;">​</a></h1><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Donne</th></tr></thead><tbody><tr><td><code>nay_car_wash.config</code></td><td><code>/nay:carwash</code> (éditeur de tunnels) et les réglages Car Wash dans <code>/nay</code>.</td></tr></tbody></table><p>Accordez-le par ACE ou par règle, voir <a href="/fr/nay-lib/permissions">Permissions</a>.</p><h2 id="api-http" tabindex="-1">API HTTP <a class="header-anchor" href="#api-http" aria-label="Permalink to &quot;API HTTP&quot;">​</a></h2><p>Activez d&#39;abord l&#39;API et créez un jeton, voir <a href="/fr/nay-lib/api">API HTTP</a>. Les routes répondent <code>{ &quot;ok&quot;: true, &quot;data&quot;: ... }</code> et demandent <code>Authorization: Bearer &lt;token&gt;</code>.</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Scope</th><th>Requête</th><th>Données</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_car_wash/v1/history</code></td><td><code>nay_car_wash.history.read</code></td><td><code>identifier</code>, <code>kind</code> (<code>tunnel</code> ou <code>manual</code>), <code>limit</code> (1 à 100, 20 par défaut), <code>before</code> (id)</td><td><code>items</code> (<code>id</code>, <code>identifier</code>, <code>kind</code>, <code>location</code>, <code>program</code>, <code>price</code>, <code>time</code>), du plus récent au plus ancien, et <code>next</code> : passez-le en <code>before</code> pour la page suivante.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/stats</code></td><td><code>nay_car_wash.stats.read</code></td><td><code>days</code> (1 à 31, 7 par défaut), <code>utcOffset</code> (minutes, -720 à 840, par défaut : l&#39;horloge du serveur)</td><td><code>utcOffset</code> utilisé, <code>total</code>, <code>byDay</code> (chaque jour listé) et <code>byLocation</code>, chacun avec <code>washes</code> et <code>revenue</code>.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/tunnels</code></td><td><code>nay_car_wash.tunnels.read</code></td><td></td><td><code>index</code>, <code>label</code>, <code>enabled</code>, <code>entry</code> pour chaque tunnel.</td></tr></tbody></table><p>Exemple :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer nay_1_xxxxxxxx&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.example.com/nay_car_wash/v1/stats?days=7&quot;</span></span></code></pre></div><h2 id="evenements-de-webhook" tabindex="-1">Événements de webhook <a class="header-anchor" href="#evenements-de-webhook" aria-label="Permalink to &quot;Événements de webhook&quot;">​</a></h2><p>Choisissez-les dans l&#39;onglet <strong>Webhooks</strong> de <code>/nay</code>, voir <a href="/fr/nay-lib/webhooks">Webhooks</a>.</p><table tabindex="0"><thead><tr><th>Événement</th><th>Quand</th><th>Données</th></tr></thead><tbody><tr><td><code>nay_car_wash.wash</code></td><td>Un lavage en tunnel est terminé.</td><td><code>player</code> (nom), <code>identifier</code>, <code>tunnel</code>, <code>program</code>, <code>price</code></td></tr><tr><td><code>nay_car_wash.manual</code></td><td>Une session de nettoyeur se termine.</td><td><code>player</code> (nom), <code>identifier</code>, <code>station</code>, <code>price</code></td></tr></tbody></table><p>Avec un webhook Discord, chaque lavage devient un embed dans votre salon, dans la langue du serveur.</p>',13)])])}const b=t(c,[["render",s]]);export{u as __pageData,b as default};
